{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 bucket access logging is not enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have server access logging configured, which prevents auditing of requests made to the bucket and hinders incident response."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket Public Access Block is not configured",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The bucket lacks an explicit aws_s3_bucket_public_access_block resource. Without this, the bucket may be susceptible to public exposure if ACLs or policies are misconfigured elsewhere."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"changeme_aws_s3_bucket_backend_simple\" {\n  force_destroy = true\n  bucket        = \"changeme-${random_id.changeme_backends_s3_bucket_name.hex}\"\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"changeme_aws_s3_bucket_backend_simple\" {\n  bucket                  = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n\nresource \"aws_s3_bucket_logging\" \"changeme_aws_s3_bucket_backend_simple\" {\n  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id\n\n  target_bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id\n  target_prefix = \"log/\"\n}",
  "fix_summary": "Added aws_s3_bucket_public_access_block to enforce strict public access controls (CKV2_AWS_6) and added aws_s3_bucket_logging to enable server access logging (CKV_AWS_18). Note: In a production environment, logs should typically be sent to a separate, dedicated log bucket with its own retention policies."
}
